 return {request:freeze(request),envelopeHash:input.envelopeHash,semanticInputHash:built.modelInput?.semanticInputHash??null,semanticContext:{input,planningManifest,source:root.task.source},admission:{mode:invocation.mode,logicalBytes,runtimeBytes,outputReservation,snapshotAdmitted:true,transportAdmission:'owned-by-http'}};
